#[derive(Parser, Debug)]
#[command(name = "mbus", version, about = "Rust browser + LLM agent")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    Run(RunArgs),
    Bench(BenchArgs),
}

#[derive(Args, Debug)]
struct RunArgs {
    #[arg(long, required_unless_present = "task_file", conflicts_with = "task_file")]
