    #[arg(long)]
    memory_max_observations: Option<usize>,
    #[arg(long)]
    memory_max_history: Option<usize>,
    #[arg(long)]
    snapshot_timeout_ms: Option<u64>,
    #[arg(long)]
    action_timeout_ms: Option<u64>,
    #[arg(long)]
    max_elements: Option<usize>,
    #[arg(long)]
